<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\TenantDomainVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Holder\TenantDomainAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantDomainAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantDomainAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getDomain returns null on a freshly created holder.
         */
        public function testDomainNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantDomainAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isDomainAssigned());
            $this->assertNull($holder->getDomain());
        }
}
class ImplWithTenantDomainAttributeHolderUnitTest
{
  use TenantDomainAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDomainRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDomain();
    }}
